module edge_detect(
    input clk, 
    input rst_n, 
    input a,
    output rise, 
    output down
);
    reg prev_a;
    reg [1:0] current_state;
    reg [1:0] next_state;
    localparam IDLE = 2'b00;
    localparam RISING_EDGE = 2'b01;
    localparam FALLING_EDGE = 2'b10;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_a <= 1'b0;
            current_state <= IDLE;
        end else begin
            prev_a <= a;
            current_state <= next_state;
        end
    end

    always @(*) begin
        case(current_state)
            IDLE: begin
                if (a == 1 && prev_a == 0) begin
                    next_state = RISING_EDGE;
                end else if (a == 0 && prev_a == 1) begin
                    next_state = FALLING_EDGE;
                end else begin
                    next_state = IDLE;
                end
            end

            RISING_EDGE: begin
                if (a == 1 && prev_a == 0) begin
                    next_state = RISING_EDGE;
                end else begin
                    next_state = IDLE;
                end
            end

            FALLING_EDGE: begin
                if (a == 0 && prev_a == 1) begin
                    next_state = FALLING_EDGE;
                end else begin
                    next_state = IDLE;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign rise = (current_state == RISING_EDGE) ? 1 : 0;
    assign down = (current_state == FALLING_EDGE) ? 1 : 0;
endmodule
